//! `audio::resample::sinc_hann` reproduces `torchaudio.transforms.Resample`
//! with its defaults to float rounding, for a large reduced ratio
//! (44100 -> 32000 is 441:320), a 2x upsample and a 3:2 downsample, output
//! length included. The constants come from
//! `tools/goldens/audio_resample_torchaudio_reference.py` (torchaudio 2.11)
//! over the same fixture.

use audio::resample::sinc_hann;

/// `0.6 sin(0.21 i) + 0.3 cos(1.7 i + 0.4)`, the reference script's fixture.
fn fixture() -> Vec<f32> {
    (0..97).map(|i| (0.6 * (0.21 * i as f64).sin() + 0.3 * (1.7 * i as f64 + 0.4).cos()) as f32).collect()
}

#[test]
fn matches_torchaudio_resample_to_float_rounding() {
    for (orig, new, want) in [(44100u32, 32000u32, &TORCHAUDIO_44100_TO_32000[..]), (16000, 32000, &TORCHAUDIO_16000_TO_32000[..]), (48000, 32000, &TORCHAUDIO_48000_TO_32000[..])] {
        let got = sinc_hann(&fixture(), orig, new);
        assert_eq!(got.len(), want.len(), "{orig} -> {new}: output length");
        let worst = got.iter().zip(want).map(|(a, b)| (a - b).abs()).fold(0f32, f32::max);
        assert!(worst < 2e-6, "{orig} -> {new}: max abs error {worst:e}");
    }
}

#[test]
fn an_equal_rate_is_the_identity() {
    assert_eq!(sinc_hann(&fixture(), 32000, 32000), fixture());
}

